    return None

def _get_tool_call_input_field_name(self, signature: type[Signature]) -> bool:
    for name, field in signature.input_fields.items():
        # Look for annotation `list[dspy.Tool]` or `dspy.Tool`
        origin = get_origin(field.annotation)
